// 2. High-Performance Canvas Image Rasterizer Engine
function addKpmgLogoToPdf(
  doc: jsPDF,
  x = 110,
  y = 10,
  width = 80,
  height = 30,
  color = "white",
) {
  const base64Data =
    color === "white"
      ? getKPMGLogoBase64().trim()
      : getKPMGLogoBase64Blue().trim();

  if (!base64Data || base64Data.startsWith("YOUR_")) {
    throw new Error("Base64 string is empty or unpopulated.");
  }

  // Format the string into a valid PNG Data URI payload
  const imageDataUri = `data:image/png;base64,${base64Data}`;

  // jsPDF injects base64 PNG data instantly onto the page context
  doc.addImage(imageDataUri, "PNG", x, y, width, height);
}

