function drawDocHeader(
  doc: jsPDF,
  pageWidth: number,
  pageHeight: number,
  onCover = false,
) {
  // Directly skip execution if the active context is the report cover page
  if (onCover) return;

  const leftMargin = 20;
  const rightMargin = 20;
  const targetY = 6; // Baseline height tracking for text alignment matching image proportion

  // 1. Configure Header Typography Styles
  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(...K.midGrey); // Standard muted dark grey accent ink

  // 2. Left Column Text: Primary Report Metadata Context
  doc.text("CONFIDENTIAL COMPLAINCE AUDIT", leftMargin, targetY);

  // 3. Right Column Text: Dynamic Document Reference Tracker String
  // Positions perfectly right-aligned matching the explicit content margin line boundary
  doc.text("DOC REF: KPMG-EUA-2026", pageWidth - rightMargin, targetY, {
    align: "right",
  });

  // 4. Accent Horizontal Border Separation Rule
  // Positioned slightly below the text layer (targetY + 3.5)
  const lineY = targetY + 3.5;
  doc.setDrawColor(...K.lightGrey);
  doc.setLineWidth(0.3); // Muted thin line style matching the reference image layout

  // Strikes a perfect vector line completely across the page from margin to margin
  doc.line(leftMargin, lineY, pageWidth - rightMargin, lineY);
}

